struct FEMenuEntry
{
    int entry_num;
};

struct MenuVTable
{
    char padding[112];
    short adjustment;
    short reserved;
    void (*OnActivate)(void *);
};

struct FEMenu
{
    char padding[116];
    MenuVTable *vtable;
};

struct PanelVTable
{
    char padding[24];
    short adjustment;
    short reserved;
    void (*TurnOn)(void *, bool);
};

struct PanelQuad
{
    char padding[404];
    PanelVTable *vtable;
};

class ExtrasFrontEnd
{
public:
    enum
    {
        ExtrasBeachesEntry,
        ExtrasSurfersEntry,
        ExtrasTrailersEntry,
        ExtrasHighScoreEntry,
        ExtrasScrapbookEntry,
        ExtrasCheatsEntry,
        ExtrasCreditsEntry,
        ExtrasWebsitesEntry,
        ExtrasLogbookEntry,
        ExtrasTHDemoEntry,
        ExtrasDemoEntryYes,
        ExtrasDemoEntryNo,
        ExtrasEndEntry
    };

    char padding0[76];
    FEMenuEntry *highlighted;
    char padding1[328];
    FEMenu *surfers;
    FEMenu *beaches;
    FEMenu *trailers;
    char padding2[16];
    PanelQuad *videos[ExtrasEndEntry];
    char padding3[36];
    PanelQuad *arrows[2][2];

    void UpdateState();
    void UpdateHelpbar();
};

__asm__(".equ UpdateHelpbar__14ExtrasFrontEnd, 0x001BA428");

static void activate(FEMenu *menu)
{
    MenuVTable *table = menu->vtable;
    table->OnActivate((char *)menu + table->adjustment);
}

static void turn_on(PanelQuad *quad, bool on)
{
    PanelVTable *table = quad->vtable;
    table->TurnOn((char *)quad + table->adjustment, on);
}

void ExtrasFrontEnd::UpdateState()
{
    bool on_beach = highlighted->entry_num == ExtrasBeachesEntry;
    bool on_surfer = highlighted->entry_num == ExtrasSurfersEntry;
    bool on_trailer = highlighted->entry_num == ExtrasTrailersEntry;
    if(on_beach) activate(beaches);
    else if(on_surfer) activate(surfers);
    else if(on_trailer) activate(trailers);

    turn_on(arrows[0][1], false);
    turn_on(arrows[0][0], on_beach || on_surfer || on_trailer);
    turn_on(arrows[1][1], false);
    turn_on(arrows[1][0], on_beach || on_surfer || on_trailer);

    for(int i=0; i<ExtrasEndEntry; i++)
        if(videos[i]) turn_on(videos[i], i == highlighted->entry_num);

    UpdateHelpbar();
}
